import proceedingsCover from '@/assets/images/state-of-the-institute/proceedings-2007-may-stavridis.jpg'
import dalySignature from '@/assets/images/state-of-the-institute/daly-signature-transparent.png'

/**
 * State of the Institute — every dated notice on the live
 * /about-us/state-of-the-institute page, newest first, as the live page lists
 * them.
 *
 * Generated from the live page's body HTML rather than hand-transcribed: ~60 KB
 * of election notices, nominee rosters, and governance documents going back to
 * 2012. Each live <hr> becomes an entry boundary and each entry's leading <h3>
 * its date. The markup is the live markup with Drupal's classes and wrappers
 * stripped (only href / src / alt kept), &nbsp; collapsed, heading levels
 * shifted down one under the page's own h1, and site-relative file links
 * resolved against www.usni.org. Wording is untouched, typos included.
 *
 * Deliberate departures from the live page, all mechanical:
 * - Two election-help links written as `https://mailto:election@usni.org/`
 *   are corrected to `mailto:`.
 * - The 2015 entry's named anchor becomes `id="ballot"` on its heading, so the
 *   2016 entry's "below" link still lands.
 * - "3 October 2019" has no rule before it on the live page; it is split into
 *   its own entry like every other dated heading.
 * - The live 2013 Stavridis entry shows the same May 2007 Proceedings cover
 *   twice, and the 2012 letter the same signature twice; one of each is kept.
 *
 * Rendered by StateOfTheInstituteEntries, which styles the markup.
 */
export interface StateOfTheInstituteEntry {
  /** As the live heading reads it — some are a month, some a full date. */
  date: string
  /** Trusted, transcribed markup. Image paths are resolved below. */
  html: string
}

const images: Record<string, string> = { ballot2016, ballot2017, proceedingsCover, dalySignature }

const resolve = (html: string) => html.replace(/\{\{(\w+)\}\}/g, (_, key: string) => images[key])

